259	
260	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
261	    @Override
262	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
263	        Owner owner = this.clinicService.findOwnerById(ownerId);
264	        if (owner != null) {
265	            Pet pet = owner.getPet(petId);
266	            if (pet != null) {
267	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
268	            }
269	        }
270	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
271	    }
272	
273	    /**
274	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
275	     * {@code telephone} is missing (null) or blank (empty or whitespace only). Bean Validation on
276	     * the request body already rejects null and empty values, but permits whitespace-only strings
277	     * for fields without a stricter pattern (e.g. {@code city}, {@code address}); this guard closes
278	     * that gap so every required field must carry a non-blank value.
279	     *
280	     * @param ownerFieldsDto the submitted owner fields
281	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
282	     */
283	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
284	        List<String> missing = new ArrayList<>();
285	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
286	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
287	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
288	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
289	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
290	        if (!missing.isEmpty()) {
291	            throw new InvalidOwnerFieldsException(missing);
292	        }
293	    }
294	
295	    /**
296	     * Rejects an owner whose supplied {@code postcode} is invalid for its {@code city}. The postcode is
297	     * optional: when absent (null) the owner is accepted unchanged, so the request contract stays
298	     * backward-compatible. When present it must be four digits and, when the city maps to a known region,
299	     * must fall within that region's fixed inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
300	     * {@code QLD 4000-4099}); a city with no known region accepts any 4-digit postcode. See
301	     * {@link PostcodeValidator}.
302	     *
303	     * @param ownerFieldsDto the submitted owner fields (its {@code city} is non-blank here,
304	     *                       {@link #rejectBlankOwnerFields} having already run)
305	     * @throws InvalidOwnerFieldsException if a postcode is present but not valid for the city
306	     */
307	    private void rejectInvalidPostcode(OwnerFieldsDto ownerFieldsDto) {
308	        if (!PostcodeValidator.isValid(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode())) {
309	            throw new InvalidOwnerFieldsException(List.of("postcode"));
310	        }
311	    }
312	
313	    private void addIfBlank(List<String> missing, String fieldName, String value) {
314	        if (value == null || value.isBlank()) {
315	            missing.add(fieldName);
316	        }
317	    }
318	
319	    /**
320	     * Normalizes the submitted {@code address} on create to its canonical form (see
321	     * {@link AddressNormalizer#normalize}) and writes it back onto the request so it is the value
322	     * stored and returned, and the form every later address comparison (the required-field check,
323	     * household duplicate detection and the shared household id) is judged on. A null address is left
324	     * untouched so {@link #rejectBlankOwnerFields} still reports it as missing; a value that is blank
325	     * after normalization likewise reduces to the empty string and is rejected there.
326	     *
327	     * @param ownerFieldsDto the submitted owner fields
328	     */
329	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
330	        String address = ownerFieldsDto.getAddress();
331	        if (address == null) {
332	            return;
333	        }
334	        ownerFieldsDto.setAddress(AddressNormalizer.normalize(address));
335	    }
336	
337	    /**
338	     * Normalizes the submitted {@code telephone} on create to its canonical form (see
339	     * {@link TelephoneNormalizer#normalize}) and writes it back onto the request so it is the value
340	     * stored and returned. Any input that does not reduce to a valid telephone is rejected with a
341	     * {@code 400 Bad Request}.
342	     *
343	     * @param ownerFieldsDto the submitted owner fields (its {@code telephone} is non-blank here,
344	     *                       {@link #rejectBlankOwnerFields} having already run)
345	     * @throws InvalidOwnerFieldsException if the telephone cannot be normalized to a valid value
346	     */
347	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
348	        String normalized = TelephoneNormalizer.normalize(ownerFieldsDto.getTelephone())
349	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("telephone")));
350	        ownerFieldsDto.setTelephone(normalized);
351	    }
352	
353	    /**
354	     * Normalizes an optionally-supplied {@code email}. When absent (null) or blank the field is left
355	     * untouched (email is optional). When present it is reduced to its canonical form (see
356	     * {@link EmailNormalizer#normalize}) and written back so it is the value stored and returned. Any
357	     * present-but-invalid address is rejected with a {@code 400 Bad Request}.
358	     *
359	     * @param ownerFieldsDto the submitted owner fields
360	     * @throws InvalidOwnerFieldsException if the email is present but not a syntactically valid address,
361	     *                                     or its domain is on the disposable-domain blocklist
362	     */
363	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
364	        String email = ownerFieldsDto.getEmail();
365	        if (email == null || email.isBlank()) {
366	            return;
367	        }
368	        String normalized = EmailNormalizer.normalize(email)
369	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("email")));
370	        if (EmailNormalizer.hasDisposableDomain(normalized)) {
371	            throw new InvalidOwnerFieldsException(List.of("email"));
372	        }
373	        ownerFieldsDto.setEmail(normalized);
374	    }
375	
376	    /**
377	     * Rejects creating an owner whose derived identity collides with an existing owner. All owner
378	     * duplicate detection is now expressed through the single derived {@code identityKey}
379	     * ({@code normalizedTelephone + '|' + email + '|' + householdId}, see {@link OwnerIdentity}),
380	     * which replaces the previously separate telephone, email and household checks. Two owners denote
381	     * the same person when their identities collide on the telephone - the identity's distinguishing
382	     * component - so a create is rejected as a {@code 409 Conflict} when another owner already carries
383	     * the same normalized telephone. Because the telephone is part of the identity, two members of the
384	     * same household with different telephones have different identities and are both allowed; an email
385	     * or a household on its own no longer makes a duplicate.
386	     *
387	     * @param ownerFieldsDto the submitted owner fields, with telephone and email already normalized
388	     *                       ({@link #normalizeTelephone}, {@link #normalizeEmail})
389	     * @param householdId    the household id derived for the owner being created (see
390	     *                       {@link HouseholdNormalizer#toHouseholdId})
391	     * @throws DuplicateOwnerIdentityException if another owner already carries the same identity
392	     */
393	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto, String householdId) {
394	        String identityKey = OwnerIdentity.identityKey(
395	            ownerFieldsDto.getTelephone(), ownerFieldsDto.getEmail(), householdId);
396	        String telephoneKey = TelephoneNormalizer.toComparisonKey(ownerFieldsDto.getTelephone());
397	        boolean inUse = this.clinicService.findAllOwners().stream()
398	            .map(Owner::getTelephone)
399	            .filter(Objects::nonNull)
400	            .map(TelephoneNormalizer::toComparisonKey)
401	            .anyMatch(telephoneKey::equals);
402	        if (inUse) {
403	            throw new DuplicateOwnerIdentityException(identityKey);
404	        }
405	    }
406	
407	    /**
408	     * Counts the existing owners (before this create) whose {@code firstName} and {@code lastName}
409	     * both match the submitted values, compared case-insensitively. The count reflects only owners
410	     * already persisted at the time of the create, so the owner being created is never included.
411	     *
412	     * @param firstName the submitted first name (non-blank here, {@link #rejectBlankOwnerFields}
413	     *                  having already run)
414	     * @param lastName  the submitted last name (non-blank here)
415	     * @return the number of existing owners sharing the same first and last name
416	     */
417	    private int countNamesakes(String firstName, String lastName) {
418	        return (int) this.clinicService.findAllOwners().stream()
419	            .filter(owner -> firstName.equalsIgnoreCase(owner.getFirstName())
420	                && lastName.equalsIgnoreCase(owner.getLastName()))
421	            .count();
422	    }
423	
424	    /**
425	     * Counts the existing owners (before this create) belonging to the given household, i.e. those
426	     * whose stored {@code householdId} equals the value derived for the owner being created. The
427	     * count reflects only owners already persisted at the time of the create, so the owner being
428	     * created is never included; callers add one to obtain the household size after this create.
429	     *
430	     * @param householdId the household identifier derived for the owner being created (see
431	     *                    {@link HouseholdNormalizer#toHouseholdId})
432	     * @return the number of existing owners already sharing that household
433	     */
434	    private int countHouseholdMembers(String householdId) {
435	        if (householdId == null) {
436	            return 0;
437	        }
438	        return (int) this.clinicService.findAllOwners().stream()
439	            .map(Owner::getHouseholdId)
440	            .filter(householdId::equals)
441	            .count();
442	    }
443	
444	    /**
445	     * Derives the household id an owner should carry from its submitted fields (see
446	     * {@link HouseholdNormalizer#toHouseholdId}). Both create and update stamp an owner with a
447	     * household id, so routing them through this single method keeps them agreed on which of the
448	     * owner's fields key the household.
449	     *
450	     * @param ownerFieldsDto the submitted owner fields (its identifying fields are non-blank here,
451	     *                       {@link #rejectBlankOwnerFields} having already run on create)
452	     * @return the owner's household id
453	     */
454	    private String householdIdFor(OwnerFieldsDto ownerFieldsDto) {
455	        return HouseholdNormalizer.toHouseholdId(
456	            ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode());
457	    }
458	
459	    /**
460	     * Rejects creating an owner that would join an existing household without declaring itself a
461	     * member. The household is keyed on (last name, postcode) through the derived {@code householdId}
462	     * (see {@link HouseholdNormalizer#toHouseholdId}), so a second owner sharing an existing owner's
463	     * last name and postcode denotes the same household. Such a create is reported as a {@code 409
464	     * Conflict} unless it opts in with {@code sharesHousehold}, in which case it is accepted as a
465	     * declared household member. Only owners already persisted (before this create) are considered.
466	     *
467	     * @param householdId     the household id derived for the owner being created
468	     * @param sharesHousehold whether the request opted in to sharing a household
469	     * @throws DuplicateOwnerHouseholdException if the household already exists and the request did not
470	     *                                          opt in with {@code sharesHousehold}
471	     */
472	    private void rejectHouseholdDuplicate(String householdId, boolean sharesHousehold) {
473	        if (sharesHousehold || householdId == null) {
474	            return;
475	        }
476	        boolean householdExists = this.clinicService.findAllOwners().stream()
477	            .map(Owner::getHouseholdId)
478	            .anyMatch(householdId::equals);
479	        if (householdExists) {
480	            throw new DuplicateOwnerHouseholdException(householdId);
481	        }
482	    }
483	
484	    /**
485	     * Finds an existing owner that the owner being created soft-matches on, or {@code null} when there
486	     * is none. The create has already cleared the hard-duplicate identity check
487	     * ({@link #rejectDuplicateIdentity}), so it is not an exact match of any existing owner; it is a
488	     * <em>possible</em> duplicate when it nevertheless shares an existing owner's {@code lastName}
489	     * (compared case-insensitively) and {@code postcode} while carrying a different normalized
490	     * telephone. The oldest such owner (the earliest persisted) is returned so the flag points at the
491	     * original record; owners with no postcode never match, since a shared postcode is required.
492	     *
493	     * @param owner the owner being created, with telephone already normalized and lastName/postcode set
494	     * @return the id of the matching existing owner, or {@code null} when the owner is not a possible
495	     *         duplicate
496	     */
497	    private Integer findPossibleDuplicate(Owner owner) {
498	        String postcode = owner.getPostcode();
499	        if (postcode == null) {
500	            return null;
501	        }
502	        String telephoneKey = TelephoneNormalizer.toComparisonKey(owner.getTelephone());
503	        return this.clinicService.findAllOwners().stream()
504	            .filter(existing -> owner.getLastName().equalsIgnoreCase(existing.getLastName()))
505	            .filter(existing -> postcode.equals(existing.getPostcode()))
506	            .filter(existing -> existing.getTelephone() != null
507	                && !telephoneKey.equals(TelephoneNormalizer.toComparisonKey(existing.getTelephone())))
508	            .map(Owner::getId)
509	            .filter(Objects::nonNull)
510	            .min(Integer::compareTo)
511	            .orElse(null);
512	    }
513	
514	    /**
515	     * Records on the owner being created whether it is a possible (soft) duplicate of an existing
516	     * owner. The match itself is decided by {@link #findPossibleDuplicate}; this method reflects its
517	     * result into the two stored fields, so the interpretation of "is a possible duplicate" lives in
518	     * one place: {@code possibleDuplicateOf} holds the matched owner's id (or {@code null} when there
519	     * is none) and {@code possibleDuplicate} is {@code true} exactly when a match was found. An owner
520	     * that opted in with {@code sharesHousehold} is a declared household member, not a suspected
521	     * duplicate, so it is never flagged.
522	     *
523	     * @param owner           the owner being created, with telephone already normalized and
524	     *                        lastName/postcode set
525	     * @param sharesHousehold whether the request opted in to sharing a household
526	     */
527	    private void markPossibleDuplicate(Owner owner, boolean sharesHousehold) {
528	        Integer possibleDuplicateOf = sharesHousehold ? null : findPossibleDuplicate(owner);
529	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
530	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
531	    }
532	
533	    /**
534	     * Rejects creating an owner whose city already holds {@link #MAX_OWNERS_PER_CITY} or more owners.
535	     * The submitted city is compared case-insensitively against every existing owner's stored city; a
536	     * city that is already at (or over) capacity is reported as a {@code 409 Conflict}.
537	     *
538	     * @param city the submitted city (non-blank here, {@link #rejectBlankOwnerFields} having already
539	     *             run)
540	     * @throws OwnerCityAtCapacityException if the city already contains the maximum number of owners
541	     */
542	    private void rejectCityAtCapacity(String city) {
543	        long ownersInCity = this.clinicService.findAllOwners().stream()
544	            .map(Owner::getCity)
545	            .filter(Objects::nonNull)
546	            .filter(city::equalsIgnoreCase)
547	            .count();
548	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
549	            throw new OwnerCityAtCapacityException(city);
550	        }
551	    }
552	
553	    /**
554	     * Resolves the effective registration date for a create, rolled onto a business day. The
555	     * supplied date is used when present, otherwise the server's current date; either way the result
556	     * is rolled forward to the next Monday when it falls on a Saturday or Sunday (see
557	     * {@link BusinessDayAdjuster#toBusinessDay}). Every value derived from the registration date - the
558	     * stored {@code registrationDate}, the membership number's year segment and the daily
559	     * create-limit's per-day count - is judged on this adjusted date.
560	     *
561	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} to
562	     *                                 default to the server's current date
563	     * @return the effective registration date, guaranteed to fall on a business day
564	     */
565	    /**
566	     * Rejects a create whose supplied {@code registrationDate} lies after the server's current date.
567	     * The raw submitted value is compared against {@link LocalDate#now()} before any business-day
568	     * adjustment; a future date cannot describe a registration that has already happened, so it is
569	     * reported as a {@code 400 Bad Request}. A {@code null} registration date (defaulted to the
570	     * server's current date) and any date on or before today are accepted.
571	     *
572	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} when
573	     *                                 omitted
574	     * @throws InvalidOwnerFieldsException if the supplied date is later than the server's current date
575	     */
576	    private void rejectFutureRegistrationDate(LocalDate suppliedRegistrationDate) {
577	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
578	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
579	        }
580	    }
581	
582	    private LocalDate effectiveRegistrationDate(LocalDate suppliedRegistrationDate) {
583	        LocalDate registrationDate =
584	            suppliedRegistrationDate != null ? suppliedRegistrationDate : LocalDate.now();
585	        return BusinessDayAdjuster.toBusinessDay(registrationDate);
586	    }
587	
588	    /**
589	     * Rejects creating an owner once {@link #MAX_OWNERS_PER_DAY} or more owners have already been
590	     * created for the given business day, judged by their stored {@code registrationDate}. Only owners
591	     * already persisted (before this create) are counted, and only those whose {@code registrationDate}
592	     * equals the adjusted registration date; a day at (or over) that limit is reported as a {@code 429
593	     * Too Many Requests}.
594	     *
595	     * @param registrationDate   the create's effective registration date, already rolled onto a
596	     *                           business day by {@link #effectiveRegistrationDate}
597	     * @param registeredThatDay  the number of owners already persisted (before this create) whose
598	     *                           {@code registrationDate} equals {@code registrationDate}
599	     * @throws OwnerDailyRegistrationLimitException if that day has already reached the maximum number of
600	     *                                              owner registrations
601	     */
602	    private void rejectDailyRegistrationLimitReached(LocalDate registrationDate, long registeredThatDay) {
603	        if (registeredThatDay >= MAX_OWNERS_PER_DAY) {
604	            throw new OwnerDailyRegistrationLimitException(registrationDate);
605	        }
606	    }
607	
608	    /**
609	     * Counts the owners already persisted (before this create) whose stored {@code registrationDate}
610	     * equals the given day. This is the shared per-day accumulation both the daily create-limit and the
611	     * bulk-signup warning are judged on.
612	     *
613	     * @param registrationDate the create's effective registration date, already rolled onto a business
614	     *                         day by {@link #effectiveRegistrationDate}
615	     * @return the number of existing owners registered on that day
616	     */
617	    private long countRegisteredOn(LocalDate registrationDate) {
618	        return this.clinicService.findAllOwners().stream()
619	            .map(Owner::getRegistrationDate)
620	            .filter(registrationDate::equals)
621	            .count();
622	    }
623	}
